private String resolveMenuGroup(ComponentMenu menu) {
    // 特例 code 优先于关键词命中，避免人工已确认的组件被规则改写
    if (SPECIAL_CODES.contains(menu.getC_menu_code())) {
        return MENU_GROUP_H5;
    }
    String hay = StringUtils.defaultString(menu.getC_menu_name())
            + StringUtils.defaultString(menu.getC_menu_identification())
            + StringUtils.defaultString(menu.getUrl());
    String lower = hay.toLowerCase();
    for (String kw : H5_KEYWORDS) {          // h5 / mobile / 移动
        if (lower.contains(kw)) {
            return MENU_GROUP_H5;
        }
    }
    return MENU_GROUP_WEB;                    // 兜底按 web 处理
}

public int backfill(Long componentId) {
    List<ComponentMenu> menus = queryComponentMenus(componentId);
    List<Map<String, Object>> payload = new ArrayList<>();
    for (ComponentMenu m : menus) {
        // 非 null 且非空串直接跳过，人工配过的一律不改
        if (StringUtils.isNotBlank(m.getC_menu_group())) {
            continue;
        }
        Map<String, Object> row = new HashMap<>(2);
        row.put("id", m.getId());
        row.put("c_menu_group", resolveMenuGroup(m));
        payload.add(row);
    }
    if (payload.isEmpty()) {
        return 0;
    }
    return componentModelService.batchUpdateComponentMenu(componentId, payload);
}

public int batchUpdateComponentMenu(Long componentId, List<Map<String, Object>> rows) {
    if (CollectionUtils.isEmpty(rows)) {
        return 0;
    }
    List<Long> ids = new ArrayList<>(rows.size());
    Map<Long, String> groupById = new HashMap<>(rows.size());
    for (Map<String, Object> row : rows) {
        String idText = String.valueOf(row.get("id"));
        // id 必须是纯数字，挡住把 code 当 id 传上来的调用方
        if (!idText.matches("\\d+")) {
            throw new BizException("菜单 id 非法: " + idText);
        }
        String group = (String) row.get("c_menu_group");
        if (!ALLOWED_GROUPS.contains(group)) {
            throw new BizException("分组值非法: " + group);
        }
        Long id = Long.valueOf(idText);
        ids.add(id);
        groupById.put(id, group);
    }
    // 一次 IN 查做存在性校验，避免逐条查库
    List<ComponentMenu> exist = componentMenuDao.queryByIds(componentId, ids);
    if (exist.size() != ids.size()) {
        throw new BizException("存在不属于该组件的菜单 id");
    }
    return componentMenuDao.batchUpdateMenuGroup(componentId, ids, groupById);
}
